import socket, struct, sys, time, select

MCAST='224.0.0.251'; PORT=5353

def enc(name):
    out=b''
    for lab in name.split('.'):
        if lab: out+=bytes([len(lab)])+lab.encode()
    return out+b'\x00'

def query(names_qtypes):
    pkts=[]
    for n,qt in names_qtypes:
        h=struct.pack('!6H',0,0,1,0,0,0)
        pkts.append(h+enc(n)+struct.pack('!HH',qt,1))
    return pkts

def parse_name(data,off):
    labs=[]; jumped=False; orig=off
    while True:
        if off>=len(data): break
        l=data[off]
        if l==0:
            off+=1; break
        if l&0xC0==0xC0:
            ptr=struct.unpack('!H',data[off:off+2])[0]&0x3FFF
            if not jumped: orig=off+2
            off=ptr; jumped=True; continue
        labs.append(data[off+1:off+1+l].decode('utf-8','replace')); off+=1+l
    return '.'.join(labs), (orig if jumped else off)

s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
s.bind(('0.0.0.0',0))
s.setsockopt(socket.IPPROTO_IP,socket.IP_MULTICAST_TTL,255)

targets=[('orie.local',1),('orie.local',255)]
for ip in sys.argv[1:]:
    targets.append(('.'.join(reversed(ip.split('.')))+'.in-addr.arpa',12))

for p in query(targets):
    s.sendto(p,(MCAST,PORT))
    time.sleep(0.02)

seen=set(); end=time.time()+6
while time.time()<end:
    r,_,_=select.select([s],[],[],0.5)
    if not r: continue
    data,addr=s.recvfrom(9000)
    try:
        qd,an,ns,ar=struct.unpack('!HHHH',data[4:12])
        off=12
        for _ in range(qd):
            _,off=parse_name(data,off); off+=4
        for _ in range(an+ns+ar):
            nm,off=parse_name(data,off)
            if off+10>len(data): break
            rt,rc,ttl,rl=struct.unpack('!HHIH',data[off:off+10]); off+=10
            rd=data[off:off+rl]
            if rt==1 and rl==4:
                val=socket.inet_ntoa(rd)
            elif rt in (12,):
                val,_=parse_name(data,off)
            else:
                val=None
            off+=rl
            if val:
                k=(addr[0],nm,rt,val)
                if k not in seen:
                    seen.add(k)
                    print(f"{addr[0]:<15} {nm}  type{rt} -> {val}")
    except Exception:
        pass
PY
